// Public loadout: only equipped slots and the equipped armor upgrade entry.
function publicEquippedLoadout(full) {
    const artifactSlots = Array.from({length:6}, (_, i) => {
        const name = Array.isArray(full.artifactSlots) ? full.artifactSlots[i] : null;
        return typeof name === 'string' && name ? name : null;
    });
    const numericStats = stats => Object.fromEntries(Object.entries(stats || {}).filter(([key, value]) =>
        !['__proto__','constructor','prototype'].includes(key) && typeof value === 'number' && Number.isFinite(value)));
    const equippedArtifactDetails = artifactSlots.map(name => {
        if (!name) return null;
        const def = serverArtifactDef(name);
        if (!def) return null;
        return {name, tier:Number(def.tier)||1, gen:Number(def.gen)||0,
            isNamedArtifact:Boolean(def.isNamedArtifact), stats:numericStats(def.stats)};
    });
    const armorUpgradeData = {};
    const armorName = typeof full.armor === 'string' ? full.armor : full.armor && full.armor.name;
    if (typeof armorName === 'string' && armorName) {
        const key = getStableArmorKeyServer(armorName);
        const upgrades = full.armorUpgradeData;
        if (upgrades && Object.prototype.hasOwnProperty.call(upgrades, key)) {
            Object.defineProperty(armorUpgradeData, key, {value:numericStats(upgrades[key]), enumerable:true});
        }
    }
    return {artifactSlots, equippedArtifactDetails, armorUpgradeData};
}

